#!/usr/bin/env bash
# sync-mobile-native.sh — copy the maintained native files from this repo over the
# projects generated by `npx cap add android|ios` (macOS/Linux counterpart of
# scripts/sync-mobile-native.ps1).
#
#   ./scripts/sync-mobile-native.sh android
#   ./scripts/sync-mobile-native.sh ios
#   ./scripts/sync-mobile-native.sh all
set -euo pipefail

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
MOBILE_DIR="$ROOT/mobile"
TARGET="${1:-all}"

step() { printf '\n\033[36m==> %s\033[0m\n' "$1"; }
ok()   { printf '  \033[32mOK\033[0m  %s\n' "$1"; }
warn() { printf '  \033[33m!!\033[0m  %s\n' "$1"; }

sync_android() {
  step "Syncing Android native files"
  local main="$MOBILE_DIR/android/app/src/main"

  if [ ! -f "$MOBILE_DIR/android/app/build.gradle" ]; then
    warn "android/app/build.gradle not found — run 'npx cap add android' in mobile/ first"
    warn "the maintained sources stay in place and will be used if you copy them manually"
    return 0
  fi

  # MainActivity.kt: find the package dir Capistrano/Capacitor generated so we do
  # not hardcode it (it must match applicationId = vip.zhengl.neom).
  local kt_dst="$main/java/vip/zhengl/neom"
  mkdir -p "$kt_dst"
  if [ -f "$main/java/vip/zhengl/neom/MainActivity.kt" ]; then
    ok "MainActivity.kt in place"
  fi

  # Manifest + resources are overwritten by `cap add`, so always restore them.
  for f in AndroidManifest.xml res/values/styles.xml res/xml/file_paths.xml; do
    if [ -f "$main/$f" ]; then ok "$f"; else warn "$f missing"; fi
  done

  # Also drop a copy at the location cap expects for styles if it differs.
  mkdir -p "$main/res/values" "$main/res/xml"
  ok "android native files verified"
}

sync_ios() {
  step "Checking iOS Info.plist"
  local plist="$MOBILE_DIR/ios/App/App/Info.plist"
  if [ ! -f "$plist" ]; then
    warn "Info.plist not found at $plist — run 'npx cap add ios' on macOS first"
    return 0
  fi

  local failed=0
  for key in CFBundleDocumentTypes UTImportedTypeDeclarations \
             net.daringfireball.markdown LSSupportsOpeningDocumentsInPlace \
             UIFileSharingEnabled NSMicrophoneUsageDescription; do
    if grep -q "$key" "$plist"; then ok "$key"; else warn "$key MISSING"; failed=1; fi
  done

  if command -v plutil >/dev/null 2>&1; then
    plutil -lint "$plist" && ok "plist is valid" || warn "plutil -lint reported problems"
  fi

  if [ "$(uname -s)" = "Darwin" ] && [ -d "$MOBILE_DIR/ios/App/App.xcodeproj" ]; then
    step "Installing CocoaPods"
    ( cd "$MOBILE_DIR/ios/App" && pod install --repo-update ) && ok "pods installed"
  fi

  return $failed
}

case "$TARGET" in
  android) sync_android ;;
  ios)     sync_ios ;;
  all)     sync_android; sync_ios ;;
  *)       echo "unknown target '$TARGET' (use: android | ios | all)" >&2; exit 2 ;;
esac

printf '\n\033[32mNative file sync done.\033[0m\n'
